 4	final class EuclideanAlgorithmsCli {
 5	    private static final BigInteger DEFAULT_FIRST_OPERAND = BigInteger.valueOf(35);
 6	    private static final BigInteger DEFAULT_SECOND_OPERAND = BigInteger.valueOf(15);
 7	    private static final String INVALID_ARGUMENT_COUNT_MESSAGE =
 8	        "Expected either zero arguments or exactly two integers.";
 9	    private static final String USAGE_TEXT = "Usage: java EuclideanAlgorithms [first second]\n"
10	        + "Prints the greatest common divisor of two integers.\n"
11	        + "When no arguments are provided, defaults to "
12	        + DEFAULT_FIRST_OPERAND
13	        + " and "
14	        + DEFAULT_SECOND_OPERAND
15	        + ".";
16	
17	    private EuclideanAlgorithmsCli() {
18	    }
19	
20	    static int run(String[] args, PrintStream out, PrintStream err) {
21	        try {
22	            if (isHelpRequest(args)) {
23	                out.println(USAGE_TEXT);
24	                return 0;
25	            }
26	
27	            out.println(parseOperands(args).gcd());
28	            return 0;
29	        } catch (IllegalArgumentException exception) {
30	            err.println(exception.getMessage());
31	            err.println(USAGE_TEXT);
32	            return 1;
33	        }
34	    }
35	
36	    static String usageText() {
37	        return USAGE_TEXT;
38	    }
39	
40	    private static boolean isHelpRequest(String[] args) {
41	        return args.length == 1 && ("--help".equals(args[0]) || "-h".equals(args[0]));
42	    }
43	
44	    private static Operands parseOperands(String[] args) {
45	        return switch (args.length) {
46	            case 0 -> new Operands(DEFAULT_FIRST_OPERAND, DEFAULT_SECOND_OPERAND);
47	            case 2 -> new Operands(parseInteger(args[0]), parseInteger(args[1]));
48	            default -> throw new IllegalArgumentException(INVALID_ARGUMENT_COUNT_MESSAGE);
49	        };
50	    }
51	
52	    private static BigInteger parseInteger(String value) {
53	        try {
54	            return new BigInteger(value);
55	        } catch (NumberFormatException exception) {
56	            throw new IllegalArgumentException("Invalid integer: " + value, exception);
57	        }
58	    }
59	}

