 3	record Operands(BigInteger first, BigInteger second) {
 4	    Operands {
 5	        first = requireOperand(first, "first");
 6	        second = requireOperand(second, "second");
 7	    }
 8	
 9	    private static BigInteger requireOperand(BigInteger operand, String name) {
10	        if (operand == null) {
11	            throw new IllegalArgumentException(name + " operand must not be null.");
12	        }
13	
14	        return operand;
15	    }
16	
17	    BigInteger gcd() {
18	        if (first.signum() == 0 && second.signum() == 0) {
19	            throw new IllegalArgumentException("At least one operand must be non-zero.");
20	        }
21	
22	        return first.abs().gcd(second.abs());
23	    }
24	}
